#!/usr/bin/env bash
set -Eeuo pipefail

# Vast.ai PROVISIONING_SCRIPT
# Installs the exact Ultra Speed Singularity MiniMax H3 Part 1 stack.
# Idempotent: existing complete model files are skipped.

LOG=/workspace/h3_ultraspeed_provision.log
mkdir -p /workspace
exec > >(tee -a "$LOG") 2>&1
trap 'echo "[ERROR] line $LINENO: $BASH_COMMAND"' ERR

echo "============================================================"
echo " H3 Ultra Speed provisioning started: $(date -Is)"
echo "============================================================"

COMFY_ROOT="${WORKSPACE:-/workspace}/ComfyUI"

for i in $(seq 1 120); do
  if [ -d "$COMFY_ROOT" ]; then break; fi
  echo "[wait] $COMFY_ROOT not ready yet ($i/120)"
  sleep 2
done

if [ ! -d "$COMFY_ROOT" ]; then
  echo "[fatal] ComfyUI not found at $COMFY_ROOT"
  exit 1
fi

mkdir -p \
  "$COMFY_ROOT/models/diffusion_models" \
  "$COMFY_ROOT/models/text_encoders" \
  "$COMFY_ROOT/models/vae" \
  "$COMFY_ROOT/models/loras" \
  "$COMFY_ROOT/custom_nodes" \
  "$COMFY_ROOT/user/default/workflows/H3_Singularity_UltraSpeed"

PY=/venv/main/bin/python
if [ ! -x "$PY" ]; then PY=python3; fi

export HF_XET_HIGH_PERFORMANCE=1
export HF_HOME=/workspace/.cache/huggingface
export HF_HUB_DISABLE_TELEMETRY=1
mkdir -p "$HF_HOME"

echo "[1/5] Installing downloader dependencies..."
"$PY" -m pip install -U "huggingface_hub>=0.35" hf_xet requests

echo "[2/5] Downloading exact model set from Hugging Face..."
"$PY" - <<'PYMODELS'
from pathlib import Path
from huggingface_hub import hf_hub_download, HfApi
import os

root = Path(os.environ.get("WORKSPACE", "/workspace")) / "ComfyUI"
api = HfApi()

items = [
    (
        "WarmBloodAban/Minimax-h3_Singularity",
        "Minimax-h3_Singularity_ref2va_v1.3_int8.safetensors",
        root / "models/diffusion_models",
        root / "models/diffusion_models/Minimax-h3_Singularity_ref2va_v1.3_int8.safetensors",
    ),
    (
        "Comfy-Org/MiniMax-H3",
        "text_encoders/qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors",
        root / "models",
        root / "models/text_encoders/qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors",
    ),
    (
        "Comfy-Org/MiniMax-H3",
        "vae/minimax_h3_video_vae_int8_convrot.safetensors",
        root / "models",
        root / "models/vae/minimax_h3_video_vae_int8_convrot.safetensors",
    ),
    (
        "Comfy-Org/MiniMax-H3",
        "vae/minimax_h3_audio_vae_fp32.safetensors",
        root / "models",
        root / "models/vae/minimax_h3_audio_vae_fp32.safetensors",
    ),
    (
        "Comfy-Org/MiniMax-H3",
        "loras/minimax_h3_ref2v_turbo_4step_v0.1_comfyui_bf16.safetensors",
        root / "models",
        root / "models/loras/minimax_h3_ref2v_turbo_4step_v0.1_comfyui_bf16.safetensors",
    ),
]

repo_info_cache = {}
def expected_size(repo, filename):
    if repo not in repo_info_cache:
        info = api.repo_info(repo, repo_type="model", files_metadata=True)
        repo_info_cache[repo] = {s.rfilename: getattr(s, "size", None) for s in info.siblings}
    return repo_info_cache[repo].get(filename)

for repo, filename, local_dir, final_path in items:
    local_dir.mkdir(parents=True, exist_ok=True)
    exp = expected_size(repo, filename)
    if final_path.exists() and final_path.stat().st_size > 0 and (exp is None or final_path.stat().st_size == exp):
        print(f"[skip] {final_path.name} | {final_path.stat().st_size/1024**3:.2f} GiB")
        continue
    print(f"[download] {repo} :: {filename}")
    got = Path(hf_hub_download(
        repo_id=repo,
        filename=filename,
        repo_type="model",
        local_dir=str(local_dir),
    ))
    if not final_path.exists():
        raise RuntimeError(f"Download finished but expected file is missing: {final_path} (returned {got})")
    if exp is not None and final_path.stat().st_size != exp:
        raise RuntimeError(f"Size mismatch for {final_path.name}: got {final_path.stat().st_size}, expected {exp}")
    print(f"[ok] {final_path} | {final_path.stat().st_size/1024**3:.2f} GiB")
PYMODELS

echo "[3/5] Installing required custom nodes..."
install_repo() {
  local url="$1"
  local dir="$2"
  if [ -d "$dir/.git" ]; then
    echo "[update] $dir"
    git -C "$dir" fetch --depth 1 origin main || true
    git -C "$dir" reset --hard origin/main || true
  else
    echo "[clone] $url -> $dir"
    rm -rf "$dir"
    git clone --depth 1 "$url" "$dir"
  fi
}

install_repo "https://github.com/kijai/ComfyUI-KJNodes.git" \
  "$COMFY_ROOT/custom_nodes/ComfyUI-KJNodes"
install_repo "https://github.com/T8mars/comfyui-minimax-h3-audio-T8.git" \
  "$COMFY_ROOT/custom_nodes/minimax-h3-audio-T8"
install_repo "https://github.com/Kosinkadink/ComfyUI-VideoHelperSuite.git" \
  "$COMFY_ROOT/custom_nodes/ComfyUI-VideoHelperSuite"
install_repo "https://github.com/TFL-TFL/ComfyUI_Text_Translation.git" \
  "$COMFY_ROOT/custom_nodes/ComfyUI_Text_Translation"

for d in \
  "$COMFY_ROOT/custom_nodes/ComfyUI-KJNodes" \
  "$COMFY_ROOT/custom_nodes/minimax-h3-audio-T8" \
  "$COMFY_ROOT/custom_nodes/ComfyUI-VideoHelperSuite" \
  "$COMFY_ROOT/custom_nodes/ComfyUI_Text_Translation"
do
  if [ -f "$d/requirements.txt" ]; then
    echo "[pip] $d/requirements.txt"
    "$PY" -m pip install -r "$d/requirements.txt"
  fi
done

echo "[4/5] Writing the original Ultra Speed workflow..."
WORKFLOW_PATH="$COMFY_ROOT/user/default/workflows/H3_Singularity_UltraSpeed/Ultra Speed Singularity Minimax H3 Workflow.json"
base64 -d > "$WORKFLOW_PATH" <<'WORKFLOW_B64'

WORKFLOW_B64

echo "[5/5] Verifying installation..."
required=(
  "$COMFY_ROOT/models/diffusion_models/Minimax-h3_Singularity_ref2va_v1.3_int8.safetensors"
  "$COMFY_ROOT/models/text_encoders/qwen3vl_32b_minimax_h3_nvfp4_awq.safetensors"
  "$COMFY_ROOT/models/vae/minimax_h3_video_vae_int8_convrot.safetensors"
  "$COMFY_ROOT/models/vae/minimax_h3_audio_vae_fp32.safetensors"
  "$COMFY_ROOT/models/loras/minimax_h3_ref2v_turbo_4step_v0.1_comfyui_bf16.safetensors"
  "$COMFY_ROOT/custom_nodes/ComfyUI-KJNodes"
  "$COMFY_ROOT/custom_nodes/minimax-h3-audio-T8"
  "$COMFY_ROOT/custom_nodes/ComfyUI-VideoHelperSuite"
  "$COMFY_ROOT/custom_nodes/ComfyUI_Text_Translation"
  "$WORKFLOW_PATH"
)

for p in "${required[@]}"; do
  if [ ! -e "$p" ]; then
    echo "[fatal] missing: $p"
    exit 1
  fi
  echo "[ok] $p"
done

touch /workspace/.h3_ultraspeed_ready

echo "============================================================"
echo " H3 ULTRA SPEED: ALL GOOD"
echo " Workflow: $WORKFLOW_PATH"
echo " Log: $LOG"
echo "============================================================"

if command -v supervisorctl >/dev/null 2>&1; then
  supervisorctl restart comfyui || true
fi
